package sentinelOwnResources_test

import (
	"testing"

	sentinelOwnResources "sharpnr-engine/sentinel/mod_resources"
	sentinelAggregatorService "sharpnr-engine/sentinel_aggregators/service"
)

// Every action constant this package exports must actually be registered.
//
// The four CRUD ids per type are GENERATED by contracts.Standard() while the
// constants are written by hand, so the two can drift silently: the module's
// guard calls would then check an action id the catalog has never heard of, and
// ValidateActions would reject a save that should have been allowed. This is
// the check that keeps them in step.
func TestEveryActionConstantIsRegistered(t *testing.T) {
	svc := sentinelAggregatorService.NewSentinelAggregatorService(
		sentinelOwnResources.NewSentinelOwnResources(nil),
	)

	constants := []string{
		sentinelOwnResources.ActionCanViewSentinelPolicy,
		sentinelOwnResources.ActionCanCreateSentinelPolicy,
		sentinelOwnResources.ActionCanEditSentinelPolicy,
		sentinelOwnResources.ActionCanDeleteSentinelPolicy,
		sentinelOwnResources.ActionCanEnableSentinelPolicy,
		sentinelOwnResources.ActionCanDisableSentinelPolicy,
		sentinelOwnResources.ActionCanSetOrganizationPermissions,

		sentinelOwnResources.ActionCanViewSentinelRole,
		sentinelOwnResources.ActionCanCreateSentinelRole,
		sentinelOwnResources.ActionCanEditSentinelRole,
		sentinelOwnResources.ActionCanDeleteSentinelRole,
		sentinelOwnResources.ActionCanAssignSentinelRole,
		sentinelOwnResources.ActionCanSetSentinelRolePermissions,

		sentinelOwnResources.ActionCanViewSentinelGroup,
		sentinelOwnResources.ActionCanCreateSentinelGroup,
		sentinelOwnResources.ActionCanEditSentinelGroup,
		sentinelOwnResources.ActionCanDeleteSentinelGroup,
		sentinelOwnResources.ActionCanManageSentinelGroupMembers,
		sentinelOwnResources.ActionCanSetSentinelGroupPermissions,
	}

	if err := svc.ValidateActions(constants); err != nil {
		t.Fatalf("a declared constant is not in the catalog: %v", err)
	}
}

// The reverse direction: every registered action must have a constant. An action
// in the catalog with no constant is one nothing can guard with — it shows up in
// the permission matrix as a tickable box that gates nothing.
func TestEveryRegisteredActionHasAConstant(t *testing.T) {
	declared := map[string]bool{
		sentinelOwnResources.ActionCanViewSentinelPolicy: true, sentinelOwnResources.ActionCanCreateSentinelPolicy: true,
		sentinelOwnResources.ActionCanEditSentinelPolicy: true, sentinelOwnResources.ActionCanDeleteSentinelPolicy: true,
		sentinelOwnResources.ActionCanEnableSentinelPolicy: true, sentinelOwnResources.ActionCanDisableSentinelPolicy: true,
		sentinelOwnResources.ActionCanSetOrganizationPermissions: true,
		sentinelOwnResources.ActionCanViewSentinelRole:           true, sentinelOwnResources.ActionCanCreateSentinelRole: true,
		sentinelOwnResources.ActionCanEditSentinelRole: true, sentinelOwnResources.ActionCanDeleteSentinelRole: true,
		sentinelOwnResources.ActionCanAssignSentinelRole: true, sentinelOwnResources.ActionCanSetSentinelRolePermissions: true,
		sentinelOwnResources.ActionCanViewSentinelGroup: true, sentinelOwnResources.ActionCanCreateSentinelGroup: true,
		sentinelOwnResources.ActionCanEditSentinelGroup: true, sentinelOwnResources.ActionCanDeleteSentinelGroup: true,
		sentinelOwnResources.ActionCanManageSentinelGroupMembers: true, sentinelOwnResources.ActionCanSetSentinelGroupPermissions: true,
	}

	provider := sentinelOwnResources.NewSentinelOwnResources(nil)
	for _, reg := range provider.Resources() {
		for _, a := range reg.Descriptor.Actions {
			if !declared[a.Name] {
				t.Errorf("action %q on %q is registered but has no exported constant", a.Name, reg.Descriptor.Type)
			}
		}
	}
}

// Sentinel's three types are organization-level: nothing houses them, and none
// declares attributes. Both matter to the engine — a HousedIn would need a
// container resolver, and an attribute would need a fact resolver.
func TestSentinelResourcesAreOrganizationLevel(t *testing.T) {
	for _, reg := range sentinelOwnResources.NewSentinelOwnResources(nil).Resources() {
		if reg.HousedIn != "" {
			t.Errorf("%s: unexpected HousedIn %q", reg.Descriptor.Type, reg.HousedIn)
		}
		if len(reg.Descriptor.Attributes) != 0 {
			t.Errorf("%s: declares attributes but has no fact resolver story", reg.Descriptor.Type)
		}
		if reg.ListInstances == nil {
			t.Errorf("%s: has no instance lister, so instance-scoped policies cannot be built", reg.Descriptor.Type)
		}
	}
}
